Definition enq_append_post (sp gp tp s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo U size TH qcache : Z) (k hdq LA lsize lcount qbytes : Z) (lchunks : list Z) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) m',
    ms' = MS (enq_regs sp gp tp s7 s8 s9 s10 s11 U size TH qcache t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6)
             F (Z_to_bv 64 0x54624) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp + -2208); (TH + OT_TQ + 24, TH + OT_TQ + 32); (LA + 8, LA + 24); (LA + 24 + 8 * lcount, LA + 32 + 8 * lcount)] m m'
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -2208)
    /\ rw_cells bsegs m' (TH + OT_TQ) [C8 (wz k); C8 (wz hdq); C8 (wz LA); C8 (wz (qbytes + size))]
    /\ rw_cells bsegs m' LA [C8 (wz 0); C8 (wz (lsize + size)); C8 (wz (lcount + 1))]
    /\ u64arr bsegs m' (LA + 24) (wlist (lchunks ++ [U + -16]))
    /\ stk bsegs m' (LA + 32 + 8 * lcount) (LA + kBatchSize).

